CREATE SCHEMA IF NOT EXISTS mapper_private;
REVOKE ALL ON SCHEMA mapper_private FROM PUBLIC;
GRANT USAGE ON SCHEMA mapper_private TO anon,authenticated,service_role;
CREATE POLICY "service delivery queue" ON public.mapper_delivery_queue FOR ALL TO service_role USING(true) WITH CHECK(true);
DO $$ DECLARE f record; args text; callargs text; ret text; wrapper text; BEGIN FOR f IN SELECT p.*,pg_get_function_identity_arguments(p.oid) ident,pg_get_function_arguments(p.oid) arguments,pg_get_function_result(p.oid) result FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('mapper_access_server','mapper_current_identity','mapper_list_members','mapper_save_member','mapper_remove_member','mapper_list_forms','mapper_form_history','mapper_decide_form','mapper_edit_form','mapper_delete_form','mapper_create_release','mapper_submit_with_receipt') LOOP SELECT string_agg('$'||i,',') INTO callargs FROM generate_series(1,f.pronargs) i; EXECUTE format('ALTER FUNCTION public.%I(%s) SET SCHEMA mapper_private',f.proname,f.ident); wrapper:=format('CREATE FUNCTION public.%I(%s) RETURNS %s LANGUAGE sql SECURITY INVOKER SET search_path=public AS %L',f.proname,f.arguments,f.result,format('SELECT %smapper_private.%I(%s)',CASE WHEN f.proretset THEN '* FROM ' ELSE '' END,f.proname,coalesce(callargs,''))); EXECUTE wrapper; EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC,anon,authenticated',f.proname,f.ident); EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO authenticated,service_role',f.proname,f.ident); IF f.proname='mapper_submit_with_receipt' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO anon',f.proname,f.ident); END IF; END LOOP; END $$;
ALTER FUNCTION public.mapper_submit_form(jsonb) SET SCHEMA mapper_private;
CREATE FUNCTION public.mapper_submit_form(_data jsonb) RETURNS bigint LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT mapper_private.mapper_submit_form(_data) $$;
REVOKE ALL ON FUNCTION public.mapper_submit_form(jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mapper_submit_form(jsonb) TO service_role;
ALTER FUNCTION public.mapper_enqueue_delivery() SET SCHEMA mapper_private;